#include <cuda_runtime.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

struct Job { uint8_t prefix[84]; uint8_t target[32]; uint64_t start, stride; };
__constant__ uint64_t RC[24]={1ULL,0x8082ULL,0x800000000000808aULL,0x8000000080008000ULL,0x808bULL,0x80000001ULL,0x8000000080008081ULL,0x8000000000008009ULL,0x8aULL,0x88ULL,0x80008009ULL,0x8000000aULL,0x8000808bULL,0x800000000000008bULL,0x8000000000008089ULL,0x8000000000008003ULL,0x8000000000008002ULL,0x8000000000000080ULL,0x800aULL,0x800000008000000aULL,0x8000000080008081ULL,0x8000000000008080ULL,0x80000001ULL,0x8000000080008008ULL};
__constant__ int ROT[25]={0,1,62,28,27,36,44,6,55,20,3,10,43,25,39,41,45,15,21,8,18,2,61,56,14};
__device__ __forceinline__ uint64_t rol(uint64_t x,int n){return n?(x<<n)|(x>>(64-n)):x;}
__device__ void keccak(uint64_t a[25]){for(int r=0;r<24;r++){uint64_t c[5],d[5],b[25];for(int x=0;x<5;x++)c[x]=a[x]^a[x+5]^a[x+10]^a[x+15]^a[x+20];for(int x=0;x<5;x++)d[x]=c[(x+4)%5]^rol(c[(x+1)%5],1);for(int i=0;i<25;i++)a[i]^=d[i%5];for(int x=0;x<5;x++)for(int y=0;y<5;y++)b[y+5*((2*x+3*y)%5)]=rol(a[x+5*y],ROT[x+5*y]);for(int x=0;x<5;x++)for(int y=0;y<5;y++)a[x+5*y]=b[x+5*y]^((~b[(x+1)%5+5*y])&b[(x+2)%5+5*y]);a[0]^=RC[r];}}
__device__ bool less_target(const uint64_t h[25],const uint8_t t[32]){for(int i=0;i<32;i++){uint8_t hb=(uint8_t)(h[i/8]>>(8*(i%8)));if(hb<t[i])return true;if(hb>t[i])return false;}return false;}
__device__ void hash_one(const Job&j,uint64_t nonce,uint64_t out[25]){uint8_t m[136]={0};for(int i=0;i<20;i++)m[i]=j.prefix[i];for(int i=0;i<8;i++)m[44+i]=(uint8_t)(nonce>>(56-8*i));for(int i=20;i<84;i++)m[i+32]=j.prefix[i];m[116]=0x01;m[135]=0x80;for(int i=0;i<25;i++)out[i]=0;for(int i=0;i<17;i++){uint64_t v=0;for(int k=0;k<8;k++)v|=(uint64_t)m[i*8+k]<<(8*k);out[i]^=v;}keccak(out);}
__global__ void mine(Job j,unsigned long long*found,unsigned long long*count){uint64_t id=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x,n=j.start+id*j.stride;uint64_t h[25];hash_one(j,n,h);atomicAdd(count,1ULL);if(less_target(h,j.target))atomicCAS(found,0xffffffffffffffffULL,n);}
static int hx(char c){return c<='9'?c-'0':(c|32)-'a'+10;} static void readhex(const char*s,uint8_t*out,int n){for(int i=0;i<n;i++)out[i]=(hx(s[i*2])<<4)|hx(s[i*2+1]);}
int main(int ac,char**av){if(ac!=5){fprintf(stderr,"usage: shibahash_cuda <device> <start> <stride> <target_hex>\n");return 2;}Job j{};int dev=atoi(av[1]);j.start=strtoull(av[2],0,10);j.stride=strtoull(av[3],0,10);readhex(av[4],j.target,32);char in[169];if(scanf("%168s",in)!=1)return 3;readhex(in,j.prefix,84);cudaError_t e=cudaSetDevice(dev);if(e!=cudaSuccess){fprintf(stderr,"cudaSetDevice: %s\n",cudaGetErrorString(e));return 6;}unsigned long long *f,*c,missing=~0ULL,zero=0;cudaMalloc(&f,8);cudaMalloc(&c,8);cudaMemcpy(f,&missing,8,cudaMemcpyHostToDevice);const int th=256,bl=4096;uint64_t batch=(uint64_t)th*bl;for(;;){cudaMemcpy(c,&zero,8,cudaMemcpyHostToDevice);mine<<<bl,th>>>(j,f,c);e=cudaDeviceSynchronize();if(e!=cudaSuccess){fprintf(stderr,"CUDA error: %s\n",cudaGetErrorString(e));return 6;}unsigned long long x,n;cudaMemcpy(&x,f,8,cudaMemcpyDeviceToHost);cudaMemcpy(&n,c,8,cudaMemcpyDeviceToHost);if(x!=missing){printf("FOUND %llu\n",x);printf("HASHES %llu\n",n);break;}printf("PROGRESS %llu\n",n);fflush(stdout);j.start+=batch*j.stride;}cudaFree(f);cudaFree(c);}
